import Foundation
import Dispatch

let url = URL(string: "http://127.0.0.1:18924/api/products")!
let semaphore = DispatchSemaphore(value: 0)
var responseData: Data?
var requestError: Error?

let task = URLSession.shared.dataTask(with: url) { data, response, error in
    if let error = error {
        requestError = error
    } else {
        responseData = data
    }
    semaphore.signal()
}
task.resume()
semaphore.wait()

guard let data = responseData else {
    FileHandle.standardError.write("Error: \(requestError?.localizedDescription ?? "Unknown")\n".data(using: .utf8)!)
    exit(1)
}

struct Product: Decodable {
    let id: Int
    let name: String
    let price: Double
    let category: String
    let stock: Int
}

let products = try JSONDecoder().decode([Product].self, from: data)
let filtered = products.filter { $0.price > 50.00 }.sorted { $0.name < $1.name }

print("=== Filtered Products (price > $50.00) ===")
print("")
for product in filtered {
    print("\(product.name): $\(String(format: "%.2f", product.price))")
}
print("")
print("Count: \(filtered.count)")
print("Total: $\(String(format: "%.2f", filtered.reduce(0) { $0 + $1.price }))")

