import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/graph.json';
    const raw = fs.readFileSync(filePath, 'utf-8');
    const data: Graph = JSON.parse(raw);

    // Build adjacency list (undirected)
    const adj = new Map<string, { node: string; weight: number }[]>();
    for (const node of data.nodes) {
        adj.set(node, []);
    }
    for (const edge of data.edges) {
        adj.get(edge.from)!.push({ node: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ node: edge.from, weight: edge.weight });
    }

    // Dijkstra's algorithm
    const dist = new Map<string, number>();
    const visited = new Set<string>();

    for (const node of data.nodes) {
        dist.set(node, Infinity);
    }
    dist.set('A', 0);

    while (visited.size < data.nodes.length) {
        let minNode: string | null = null;
        let minDist = Infinity;
        for (const node of data.nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                minNode = node;
            }
        }

        if (minNode === null || minDist === Infinity) break;

        visited.add(minNode);

        const neighbors = adj.get(minNode)!;
        for (const { node, weight } of neighbors) {
            if (!visited.has(node)) {
                const newDist = dist.get(minNode)! + weight;
                if (newDist < dist.get(node)!) {
                    dist.set(node, newDist);
                }
            }
        }
    }

    // Output
    const sortedNodes = [...data.nodes].sort();
    console.log('=== Shortest Paths from A ===');
    console.log('');
    for (const node of sortedNodes) {
        console.log(`A -> ${node}: ${dist.get(node)}`);
    }
}

main();

