import * as fs from 'fs';

function isObject(val: unknown): val is Record<string, unknown> {
  return val !== null && typeof val === 'object' && !Array.isArray(val);
}

function canonicalize(val: unknown): string {
  if (val === null || val === undefined) return 'null';
  if (Array.isArray(val)) {
    return '[' + val.map(canonicalize).join(',') + ']';
  }
  if (typeof val === 'object') {
    const obj = val as Record<string, unknown>;
    const keys = Object.keys(obj).sort();
    return '{' + keys.map((k) => JSON.stringify(k) + ':' + canonicalize(obj[k])).join(',') + '}';
  }
  return JSON.stringify(val);
}

function deepMerge(a: unknown, b: unknown): unknown {
  if (Array.isArray(a) && Array.isArray(b)) {
    const result: unknown[] = [...a];
    const seen = new Set<string>();
    for (const item of a) {
      seen.add(canonicalize(item));
    }
    for (const item of b) {
      const key = canonicalize(item);
      if (!seen.has(key)) {
        seen.add(key);
        result.push(item);
      }
    }
    return result;
  }

  if (isObject(a) && isObject(b)) {
    const result: Record<string, unknown> = {};
    const allKeys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
    for (const key of allKeys) {
      if (key in a && key in b) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }

  return b;
}

function sortKeys(val: unknown): unknown {
  if (Array.isArray(val)) {
    return val.map(sortKeys);
  }
  if (isObject(val)) {
    const sorted: Record<string, unknown> = {};
    const keys = Object.keys(val).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(val[key]);
    }
    return sorted;
  }
  return val;
}

function main(): void {
  const pathA = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/config_a.json';
  const pathB = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/config_b.json';

  const a: unknown = JSON.parse(fs.readFileSync(pathA, 'utf-8'));
  const b: unknown = JSON.parse(fs.readFileSync(pathB, 'utf-8'));

  const merged = deepMerge(a, b);
  const sorted = sortKeys(merged);

  process.stdout.write(JSON.stringify(sorted, null, 2) + '\n');
}

main();

