import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/employees.csv";

        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                lines.add(line);
            }
        }

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        double maxSalary = 0;
        String highestPaidName = "";
        double totalBudget = 0;

        for (int i = 1; i < lines.size(); i++) {
            String line = lines.get(i).trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(",");
            if (parts.length < 6) continue;

            String name = parts[1].trim();
            String dept = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim());

            deptSalaries.computeIfAbsent(dept, k -> new ArrayList<>()).add(salary);
            deptCount.merge(dept, 1, Integer::sum);
            totalBudget += salary;

            if (salary > maxSalary) {
                maxSalary = salary;
                highestPaidName = name;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            sb.append(String.format("  %s: $%,.2f\n", entry.getKey(), avg));
        }

        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%,.0f)\n", highestPaidName, maxSalary));

        sb.append("\n");
        sb.append("Departments with >2 employees:\n");

        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                sb.append(String.format("  %s (%d employees)\n", entry.getKey(), entry.getValue()));
            }
        }

        sb.append("\n");
        sb.append(String.format("Total Budget: $%,.0f\n", totalBudget));

        System.out.print(sb.toString());
    }
}

