use std::collections::HashMap;
use std::fs;

fn format_f64_with_commas(n: f64, decimals: usize) -> String {
    let s = format!("{:.*}", decimals, n);
    let is_negative = s.starts_with('-');
    let abs_str = if is_negative { &s[1..] } else { &s };
    let (int_part, dec_part) = match abs_str.find('.') {
        Some(idx) => (&abs_str[..idx], &abs_str[idx + 1..]),
        None => (abs_str, ""),
    };

    let mut result = String::new();
    if is_negative {
        result.push('-');
    }
    let chars: Vec<char> = int_part.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && (chars.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*c);
    }
    if !dec_part.is_empty() {
        result.push('.');
        result.push_str(dec_part);
    }
    result
}

fn format_i64_with_commas(n: i64) -> String {
    let is_negative = n < 0;
    let abs = if is_negative { (-n).to_string() } else { n.to_string() };
    let mut result = String::new();
    if is_negative {
        result.push('-');
    }
    let chars: Vec<char> = abs.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && (chars.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*c);
    }
    result
}

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/employees.csv";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_paid: (String, f64) = (String::new(), 0.0);
    let mut total_budget: f64 = 0.0;
    let mut dept_counts: HashMap<String, usize> = HashMap::new();

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|f| f.trim()).collect();
        if fields.len() < 6 {
            continue;
        }
        let _employee_id = fields[0];
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        dept_salaries.entry(department.clone()).or_insert_with(Vec::new).push(salary);
        *dept_counts.entry(department).or_insert(0) += 1;
        total_budget += salary;

        if salary > highest_paid.1 {
            highest_paid = (name, salary);
        }
    }

    let mut depts: Vec<&String> = dept_salaries.keys().collect();
    depts.sort();

    print!("=== Salary Report ===\n");
    print!("\n");
    print!("Average Salary by Department:\n");
    for dept in &depts {
        let salaries = &dept_salaries[*dept];
        let avg: f64 = salaries.iter().sum::<f64>() / salaries.len() as f64;
        print!("  {}: ${}\n", dept, format_f64_with_commas(avg, 2));
    }
    print!("\n");
    print!("Highest Paid: {} (${})\n", highest_paid.0, format_i64_with_commas(highest_paid.1 as i64));
    print!("\n");
    print!("Departments with >2 employees:\n");
    let mut depts_sorted: Vec<&String> = dept_counts.keys().collect();
    depts_sorted.sort();
    for dept in &depts_sorted {
        let count = dept_counts[*dept];
        if count > 2 {
            print!("  {} ({} employees)\n", dept, count);
        }
    }
    print!("\n");
    print!("Total Budget: ${}\n", format_i64_with_commas(total_budget as i64));
}

