use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fs;

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/app.log";
    let content = fs::read_to_string(&path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let open_bracket = line.find('[').unwrap_or(0);
        let close_bracket = line.find(']').unwrap_or(0);
        let timestamp = &line[open_bracket + 1..close_bracket];

        let rest = &line[close_bracket + 1..].trim_start();

        // Level: first token
        let space_pos = rest.find(' ').unwrap_or(rest.len());
        let level = &rest[..space_pos];

        // After level: " (component) - message"
        let after_level = rest[space_pos..].trim_start();

        // Component: between ( and )
        let open_paren = after_level.find('(').unwrap_or(0);
        let close_paren = after_level.find(')').unwrap_or(0);
        let component = &after_level[open_paren + 1..close_paren];

        // Message: everything after ") - "
        let after_component = &after_level[close_paren + 1..];
        let message = after_component.trim_start_matches(" - ").to_string();

        // Count by level
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // Count errors by component
        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.clone());
        }

        // Count by hour (timestamp is "YYYY-MM-DD HH:MM:SS")
        let hour = &timestamp[11..13];
        *hour_counts.entry(hour.to_string()).or_insert(0) += 1;
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(c, n)| (c.clone(), *n))
        .unwrap_or_else(|| ("N/A".to_string(), 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (top_hour, top_hour_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(h, n)| (h.clone(), *n))
        .unwrap_or_else(|| ("00".to_string(), 0));
    println!("Busiest Hour: {}:00 ({} entries)", top_hour, top_hour_count);
}

