import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Set;

public class Main {
    static String json;
    static int pos;

    public static void main(String[] args) throws IOException {
        json = new String(Files.readAllBytes(Paths.get(
            "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/graph.json")));
        pos = 0;
        Object root = parseValue();

        @SuppressWarnings("unchecked")
        Map<String, Object> obj = (Map<String, Object>) root;

        @SuppressWarnings("unchecked")
        List<String> nodes = (List<String>) obj.get("nodes");
        @SuppressWarnings("unchecked")
        List<Map<String, Object>> edges = (List<Map<String, Object>>) obj.get("edges");

        Map<String, Map<String, Double>> adj = new HashMap<>();
        for (String n : nodes) adj.putIfAbsent(n, new HashMap<>());
        for (Map<String, Object> e : edges) {
            String from = (String) e.get("from");
            String to = (String) e.get("to");
            double w = ((Number) e.get("weight")).doubleValue();
            adj.putIfAbsent(from, new HashMap<>());
            adj.putIfAbsent(to, new HashMap<>());
            adj.get(from).merge(to, w, Math::min);
            adj.get(to).merge(from, w, Math::min);
        }

        Set<String> allNodes = new HashSet<>(adj.keySet());
        for (String n : nodes) allNodes.add(n);

        Map<String, Double> dist = new HashMap<>();
        for (String n : allNodes) dist.put(n, Double.POSITIVE_INFINITY);
        dist.put("A", 0.0);

        PriorityQueue<State> pq = new PriorityQueue<>(Comparator.comparingDouble(s -> s.d));
        pq.add(new State(0.0, "A"));

        while (!pq.isEmpty()) {
            State s = pq.poll();
            if (s.d > dist.get(s.n)) continue;
            for (Map.Entry<String, Double> e : adj.get(s.n).entrySet()) {
                double nd = s.d + e.getValue();
                if (nd < dist.get(e.getKey())) {
                    dist.put(e.getKey(), nd);
                    pq.add(new State(nd, e.getKey()));
                }
            }
        }

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sorted = new ArrayList<>(allNodes);
        Collections.sort(sorted);
        for (String n : sorted) {
            double d = dist.get(n);
            if (Double.isInfinite(d)) {
                System.out.println("A -> " + n + ": unreachable");
            } else if (d == Math.floor(d)) {
                System.out.println("A -> " + n + ": " + (long) d);
            } else {
                System.out.println("A -> " + n + ": " + d);
            }
        }
    }

    static class State {
        double d;
        String n;
        State(double d, String n) { this.d = d; this.n = n; }
    }

    // ---------- Minimal JSON parser ----------

    static Object parseValue() {
        skipWs();
        char c = json.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        return parseNumberOrLiteral();
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++; // consume '{'
        skipWs();
        if (pos < json.length() && json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWs();
            String key = parseString();
