    public static void main(String[] args) throws Exception {
        Path root = Paths.get("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/project_tree");

        Map<String, List<String[]>> extMap = new TreeMap<>();
        Set<String> visitedDirs = new HashSet<>();

        if (Files.isDirectory(root)) {
            walk(root, root, extMap, visitedDirs);
        }

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;
        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            for (String[] f : entry.getValue()) {
                totalFiles++;
                totalLines += Long.parseLong(f[1]);
                totalChars += Long.parseLong(f[2]);
            }
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> files = entry.getValue();

            long extLines = 0;
            long extChars = 0;
            for (String[] f : files) {
                extLines += Long.parseLong(f[1]);
                extChars += Long.parseLong(f[2]);
            }

