            }
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    static void walk(Path dir, Path root, Map<String, List<String[]>> extMap, Set<String> visitedDirs) throws IOException {
        String canonical = dir.toAbsolutePath().normalize().toString();
        if (!visitedDirs.add(canonical)) return;

        File[] files = dir.toFile().listFiles();
        if (files == null) return;

        Arrays.sort(files, Comparator.comparing(File::getName));

        for (File file : files) {
            Path filePath = file.toPath();

            if (Files.isSymbolicLink(filePath)) continue;

            if (file.isDirectory()) {
                walk(filePath, root, extMap, visitedDirs);
            } else if (file.isFile()) {
                String relPath = root.relativize(filePath).toString().replace('\\', '/');

                byte[] bytes = Files.readAllBytes(filePath);
                long charCount = bytes.length;

                long lineCount = 0;
                if (bytes.length > 0) {
                    for (byte b : bytes) {
                        if (b == '\n') lineCount++;
                    }
                    if (bytes[bytes.length - 1] != '\n') lineCount++;
                }

                String name = file.getName();
                String ext = "";
                int dotIdx = name.lastIndexOf('.');
                if (dotIdx > 0) {
                    ext = name.substring(dotIdx);
                }

                String[] entry = new String[]{relPath, String.valueOf(lineCount), String.valueOf(charCount)};
                extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(entry);
            }
        }

        for (List<String[]> list : extMap.values()) {
            list.sort(Comparator.comparing(a -> a[0]));
        }
    }
