        List<Map<String, Object>> filtered = new ArrayList<>();
        for (Object obj : products) {
            Map<String, Object> map = (Map<String, Object>) obj;
            double price = ((Number) map.get("price")).doubleValue();
            if (price > 50.00) {
                filtered.add(map);
