static char *run_cmd(const char *cmd) {
    size_t cap = 4096;
    char *buf = (char *)malloc(cap);
    if (!buf) return NULL;
    buf[0] = '\0';

    FILE *fp = popen(cmd, "r");
    if (!fp) {
        free(buf);
        return NULL;
    }

    size_t total = 0;
    size_t space = cap - 1;
    int c;
    while ((c = fgetc(fp)) != EOF) {
        if (total + 1 >= cap) {
            cap *= 2;
            char *nb = (char *)realloc(buf, cap);
            if (!nb) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = nb;
            space = cap - 1;
        }
        buf[total++] = (char)c;
        space--;
    }
    pclose(fp);
    buf[total] = '\0';

    while (total > 0 &&
           (buf[total - 1] == '\n' || buf[total - 1] == '\r' ||
            buf[total - 1] == ' '  || buf[total - 1] == '\t')) {
        buf[--total] = '\0';
    }

    return buf;
}

int main(void) {
    char *hostname = run_cmd("hostname");
    char *os       = run_cmd("uname -s");
    char *arch     = run_cmd("uname -m");
    char *username = run_cmd("whoami");

    static const char *fb = "unknown";
    if (!hostname) hostname = (char *)fb;
    if (!os)       os       = (char *)fb;
    if (!arch)     arch     = (char *)fb;
    if (!username) username = (char *)fb;

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    if (hostname != (char *)fb) free(hostname);
    if (os != (char *)fb)       free(os);
    if (arch != (char *)fb)     free(arch);
    if (username != (char *)fb) free(username);

    return 0;
}

