#include <string.h>
#include <sys/types.h>

#define _POSIX_C_SOURCE 200809L

typedef struct {
    char *key;
    long count;
} Item;

static void *xrealloc(void *p, size_t n) {
    void *q = realloc(p, n);
    if (!q) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    return q;
}

static char *xstrdup(const char *s) {
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (!p) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    memcpy(p, s, n);
    return p;
}

static void add_item(Item **arr, size_t *n, size_t *cap, const char *key, long inc, int unique) {
    for (size_t i = 0; i < *n; i++) {
        if (strcmp((*arr)[i].key, key) == 0) {
            if (!unique) (*arr)[i].count += inc;
            return;
        }
    }
    if (*n == *cap) {
        *cap = *cap ? *cap * 2 : 16;
        *arr = xrealloc(*arr, *cap * sizeof(Item));
    }
    (*arr)[*n].key = xstrdup(key);
    (*arr)[*n].count = inc;
    (*n)++;
}

static int cmp_items(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    return strcmp(x->key, y->key);
}

int main(void) {
    const char *path =
        "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ov59n0bl/app.log";
