            line[--len] = '\0';
        if (len < 21 || line[0] != '[')
            continue;

        if (line[12] >= '0' && line[12] <= '9' && line[13] >= '0' && line[13] <= '9') {
            int h = (line[12] - '0') * 10 + (line[13] - '0');
            if (h >= 0 && h < 24)
                hours[h]++;
        }

        char *close = strchr(line, ']');
        if (!close)
