            bestcount = hours[i];
            besthour = i;
        }
    }

    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (size_t i = 0; i < ln; i++)
        printf("  %s: %ld\n", levels[i].key, levels[i].count);
    printf("\n");
    printf("Component with Most Errors: %s (%ld errors)\n", bestcomp, bestcompcount);
    printf("\n");
    printf("Unique Error Messages:\n");
    for (size_t i = 0; i < mn; i++)
        printf("  - %s\n", msgs[i].key);
    printf("\n");
    printf("Busiest Hour: %02d:00 (%ld entries)\n", besthour, bestcount);

    for (size_t i = 0; i < ln; i++) free(levels[i].key);
