    fn parse_literal(&mut self, literal: &str, value: Json) -> Json {
        let lit_bytes = literal.as_bytes();
        for i in 0..lit_bytes.len() {
            if self.pos + i >= self.input.len() || self.input[self.pos + i] != lit_bytes[i] {
                panic!("Invalid literal at position {}", self.pos);
            }
        }
        self.pos += lit_bytes.len();
        value
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut result = String::new();
        loop {
            self.skip_whitespace();
            let c = self.input[self.pos] as char;
            self.pos += 1;
            if c == '"' {
                break;
            } else if c == '\\' {
                let esc = self.input[self.pos] as char;
                self.pos += 1;
                match esc {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'u' => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            let h = self.input[self.pos] as char;
                            self.pos += 1;
                            code = code * 16 + h.to_digit(16).unwrap() as u32;
                        }
                        // Handle surrogate pairs
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.pos + 1 < self.input.len()
                                && self.input[self.pos] as char == '\\'
                                && self.input[self.pos + 1] as char == 'u'
                            {
                                self.pos += 2;
                                let mut lo = 0u32;
                                for _ in 0..4 {
                                    let h = self.input[self.pos] as char;
                                    self.pos += 1;
                                    lo = lo * 16 + h.to_digit(16).unwrap() as u32;
                                }
                                let cp = 0x10000 + ((code - 0xD800) << 10) + (lo - 0xDC00);
                                result.push(char::from_u32(cp).unwrap());
                            } else {
                                result.push('\u{FFFD}');
                            }
                        } else {
                            result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                    }
                    _ => panic!("Invalid escape at position {}", self.pos - 1),
                }
            } else {
                result.push(c);
            }
        }
        result
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.input[self.pos] == b'-' {
            self.pos += 1;
        }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') {
                self.pos += 1;
            }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        Json::Number(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Json::Array(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or ']' at position {}", self.pos),
            }
        }
        Json::Array(items)
    }

    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.expect(b':');
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or '}}' at position {}", self.pos),
            }
        }
        Json::Object(map)
    }
}

fn merge(a: Json, b: Json) -> Json {
    match (a, b) {
        (Json::Object(mut oa), Json::Object(ob)) => {
            for (k, v) in ob {
                match oa.remove(&k) {
                    Some(existing) => {
                        oa.insert(k.clone(), merge(existing, v));
                    }
                    None => {
                        oa.insert(k, v);
                    }
                }
            }
            Json::Object(oa)
        }
        (Json::Array(mut a_items), Json::Array(b_items)) => {
            for item in b_items {
                if !a_items.iter().any(|existing| existing == &item) {
                    a_items.push(item);
                }
            }
            Json::Array(a_items)
        }
        (_, b) => b,
    }
}

fn fmt_number(n: f64) -> String {
    if n == n.floor() && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn serialize(value: &Json, indent: usize, out: &mut String) {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match value {
        Json::Null => out.push_str("null"),
        Json::Bool(b) => {
            if *b {
                out.push_str("true");
            } else {
                out.push_str("false");
            }
        }
        Json::Number(n) => {
            out.push_str(&fmt_number(*n));
        }
        Json::String(s) => {
            out.push('"');
            for c in s.chars() {
                match c {
                    '"' => out.push_str("\\\""),
                    '\\' => out.push_str("\\\\"),
                    '\n' => out.push_str("\\n"),
                    '\r' => out.push_str("\\r"),
                    '\t' => out.push_str("\\t"),
                    '\u{0008}' => out.push_str("\\b"),
                    '\u{000C}' => out.push_str("\\f"),
                    c if (c as u32) < 0x20 => {
                        out.push_str(&format!("\\u{:04x}", c as u32));
                    }
                    c => out.push(c),
                }
            }
            out.push('"');
        }
        Json::Array(items) => {
            if items.is_empty() {
                out.push_str("[]");
            } else {
                out.push_str("[\n");
                for (i, item) in items.iter().enumerate() {
                    out.push_str(&pad_inner);
                    serialize(item, indent + 1, out);
                    if i + 1 < items.len() {
                        out.push(',');
                    }
                    out.push('\n');
                }
                out.push_str(&pad);
                out.push(']');
            }
        }
        Json::Object(map) => {
            if map.is_empty() {
                out.push_str("{}");
            } else {
                out.push_str("{\n");
                let len = map.len();
                for (i, (k, v)) in map.iter().enumerate() {
                    out.push_str(&pad_inner);
                    out.push('"');
                    for c in k.chars() {
                        match c {
                            '"' => out.push_str("\\\""),
                            '\\' => out.push_str("\\\\"),
                            '\n' => out.push_str("\\n"),
                            '\r' => out.push_str("\\r"),
                            '\t' => out.push_str("\\t"),
                            '\u{0008}' => out.push_str("\\b"),
                            '\u{000C}' => out.push_str("\\f"),
                            c if (c as u32) < 0x20 => {
                                out.push_str(&format!("\\u{:04x}", c as u32));
                            }
                            c => out.push(c),
                        }
                    }
                    out.push('"');
                    out.push_str(": ");
                    serialize(v, indent + 1, out);
                    if i + 1 < len {
                        out.push(',');
                    }
                    out.push('\n');
                }
                out.push_str(&pad);
                out.push('}');
            }
        }
    }
}

