import Foundation

func readJSON(_ path: String) -> Any {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    let obj = try! JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed])
    return obj
}

func isObject(_ value: Any) -> Bool {
    return value is [String: Any]
}

func isArray(_ value: Any) -> Bool {
    return value is [Any]
}

func canonicalJSON(_ value: Any) -> String {
    let obj: Any
    if isObject(value) || isArray(value) {
        obj = value
    } else {
        obj = [value]
    }
    let data = try! JSONSerialization.data(withJSONObject: obj, options: [.sortedKeys])
    let str = String(data: data, encoding: .utf8)!
    if isObject(value) || isArray(value) {
        return str
    } else {
        return String(str.dropFirst().dropLast())
    }
}

func merge(_ a: Any, _ b: Any) -> Any {
    if isObject(a) && isObject(b) {
        let aDict = a as! [String: Any]
        let bDict = b as! [String: Any]
        var result: [String: Any] = [:]
        let allKeys = Set(aDict.keys).union(bDict.keys)
        for key in allKeys {
            if let aVal = aDict[key], let bVal = bDict[key] {
                result[key] = merge(aVal, bVal)
            } else if let aVal = aDict[key] {
                result[key] = aVal
            } else if let bVal = bDict[key] {
                result[key] = bVal
            }
        }
        return result
    } else if isArray(a) && isArray(b) {
        let aArr = a as! [Any]
        let bArr = b as! [Any]
        var result: [Any] = []
        var seen = Set<String>()
        for item in aArr {
            let key = canonicalJSON(item)
            if !seen.contains(key) {
                seen.insert(key)
                result.append(item)
            }
        }
        for item in bArr {
            let key = canonicalJSON(item)
            if !seen.contains(key) {
                seen.insert(key)
                result.append(item)
            }
        }
        return result
    } else {
        return b
    }
}

