func multiply(_ m1: [[Int]], _ m2: [[Int]]) -> [[Int]] {
    let rows = m1.count
    let cols = m2[0].count
    let inner = m1[0].count
    var result = [[Int]](repeating: [Int](repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            var sum = 0
            for k in 0..<inner {
                sum += m1[i][k] * m2[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

func determinant(_ m: [[Int]]) -> Int {
    let n = m.count
    if n == 1 { return m[0][0] }
    if n == 2 { return m[0][0] * m[1][1] - m[0][1] * m[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n where k != j {
                row.append(m[i][k])
            }
            minor.append(row)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * m[0][j] * determinant(minor)
    }
    return det
}

