    const inter = m1[0].length;
    const cols = m2[0].length;
    const result: Matrix = Array.from({ length: rows }, () => Array(cols).fill(0));
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            for (let k = 0; k < inter; k++) {
                result[i][j] += m1[i][k] * m2[k][j];
