} Product;

static int compare_products(const void *a, const void *b) {
    const Product *pa = (const Product *)a;
    const Product *pb = (const Product *)b;
    return strcmp(pa->name, pb->name);
}

static void json_get_string(const char *obj, const char *key, char *out, size_t out_size) {
    char pattern[256];
    snprintf(pattern, sizeof(pattern), "\"%s\":", key);
    const char *p = strstr(obj, pattern);
    if (!p) {
        snprintf(pattern, sizeof(pattern), "\"%s\" :", key);
        p = strstr(obj, pattern);
    }
    if (!p) { out[0] = '\0'; return; }
    p += strlen(pattern);
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    if (*p != '"') { out[0] = '\0'; return; }
    p++;
    size_t i = 0;
    while (*p && *p != '"' && i < out_size - 1) {
        if (*p == '\\') {
            p++;
            if (*p == '"') out[i++] = '"';
            else if (*p == '\\') out[i++] = '\\';
            else if (*p == '/') out[i++] = '/';
            else if (*p == 'n') out[i++] = '\n';
            else if (*p == 't') out[i++] = '\t';
            else if (*p == 'r') out[i++] = '\r';
            else if (*p == 'b') out[i++] = '\b';
            else if (*p == 'f') out[i++] = '\f';
            else if (*p == 'u') {
                out[i++] = '?';
                p += 4;
            }
            else out[i++] = *p;
        } else {
            out[i++] = *p;
        }
        p++;
    }
    out[i] = '\0';
}

static double json_get_number(const char *obj, const char *key) {
    char pattern[256];
    snprintf(pattern, sizeof(pattern), "\"%s\":", key);
    const char *p = strstr(obj, pattern);
    if (!p) {
        snprintf(pattern, sizeof(pattern), "\"%s\" :", key);
        p = strstr(obj, pattern);
    }
    if (!p) return 0.0;
    p += strlen(pattern);
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    return atof(p);
}

