fn walk(dir: &Path, root: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for item in entries.flatten() {
        let path = item.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(&path, root, files);
        } else if path.is_file() {
            let rel = path.strip_prefix(root).unwrap_or(&path);
            let rel_str = rel.to_string_lossy().replace('\\', "/");
            let (lines, chars) = file_stats(&path);
            files.push((rel_str, lines, chars));
        }
    }
