    let mut file = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return (0, 0),
    };

    let mut buf = [0u8; 8192];
    loop {
        match file.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => contents.extend_from_slice(&buf[..n]),
            Err(_) => break,
        }
    }

    let chars = contents.len() as u64;

    if contents.is_empty() {
        return (0, chars);
    }

    let newline_count = contents.iter().filter(|&&b| b == b'\n').count() as u64;
    let lines = if contents.last() == Some(&b'\n') {
        newline_count
    } else {
        newline_count + 1
    };

    (lines, chars)
}

