            for (Object k : mapA.keySet()) allKeys.add((String) k);
            for (Object k : mapB.keySet()) allKeys.add((String) k);
            for (String key : allKeys) {
                boolean inA = mapA.containsKey(key);
                boolean inB = mapB.containsKey(key);
                if (inA && inB) {
                    result.put(key, deepMerge(mapA.get(key), mapB.get(key)));
                } else if (inA) {
                    result.put(key, mapA.get(key));
                } else {
                    result.put(key, mapB.get(key));
