            @SuppressWarnings("unchecked")
            Map<String, Object> map = (Map<String, Object>) obj;
            if (map.isEmpty()) { sb.append("{}"); return; }
            List<String> keys = new ArrayList<>(map.keySet());
            Collections.sort(keys);
            sb.append("{\n");
            List<String> entries = new ArrayList<>();
            for (String key : keys) {
                StringBuilder entry = new StringBuilder();
                entry.append(padInner).append("\"").append(escapeString(key)).append("\": ");
                printJson(map.get(key), indent + 1, entry);
                entries.add(entry.toString());
            }
            sb.append(String.join(",\n", entries));
            sb.append("\n").append(pad).append("}");
        } else if (obj instanceof List) {
            List<?> list = (List<?>) obj;
            if (list.isEmpty()) { sb.append("[]"); return; }
            sb.append("[\n");
            List<String> items = new ArrayList<>();
            for (Object item : list) {
                StringBuilder itemSb = new StringBuilder();
                itemSb.append(padInner);
                printJson(item, indent + 1, itemSb);
                items.add(itemSb.toString());
            }
            sb.append(String.join(",\n", items));
            sb.append("\n").append(pad).append("]");
        } else if (obj instanceof String) {
            sb.append("\"").append(escapeString((String) obj)).append("\"");
