                char to_name[MAX_NAME] = "";
                double weight = 0;

                p = skip_ws(p);
                if (strncmp(p, "\"from\"", 6) == 0) {
                    p += 6;
                    p = skip_ws(p);
                    if (*p == ':') p++;
                    p = parse_json_string(p, from_name, MAX_NAME);
                }
                p = skip_ws(p);
                if (*p == ',') p++;
                p = skip_ws(p);
                if (strncmp(p, "\"to\"", 4) == 0) {
                    p += 4;
                    p = skip_ws(p);
                    if (*p == ':') p++;
                    p = parse_json_string(p, to_name, MAX_NAME);
                }
                p = skip_ws(p);
                if (*p == ',') p++;
                p = skip_ws(p);
                if (strncmp(p, "\"weight\"", 8) == 0) {
                    p += 8;
                    p = skip_ws(p);
                    if (*p == ':') p++;
                    p = parse_json_number(p, &weight);
                }
                p = skip_ws(p);
                if (*p == '}') p++;

                /* Find indices */
                int from_idx = -1, to_idx = -1;
                for (int i = 0; i < node_count; i++) {
                    if (strcmp(nodes[i].name, from_name) == 0) from_idx = i;
                    if (strcmp(nodes[i].name, to_name) == 0) to_idx = i;
                }

                if (from_idx >= 0 && to_idx >= 0) {
                    Edge *e1 = malloc(sizeof(Edge));
                    e1->to = to_idx;
                    e1->weight = weight;
                    e1->next = nodes[from_idx].edges;
                    nodes[from_idx].edges = e1;

                    Edge *e2 = malloc(sizeof(Edge));
                    e2->to = from_idx;
                    e2->weight = weight;
                    e2->next = nodes[to_idx].edges;
                    nodes[to_idx].edges = e2;
                }
            }
        }
    }

    /* Find source node "A" */
    int src = -1;
    for (int i = 0; i < node_count; i++) {
        if (strcmp(nodes[i].name, "A") == 0) {
            src = i;
            break;
        }
    }

    /* Dijkstra */
    double *dist = malloc(node_count * sizeof(double));
    int *visited = malloc(node_count * sizeof(int));
    for (int i = 0; i < node_count; i++) {
        dist[i] = INF;
        visited[i] = 0;
    }
    if (src >= 0) dist[src] = 0.0;

    for (int iter = 0; iter < node_count; iter++) {
        int u = -1;
        double min_d = INF;
        for (int i = 0; i < node_count; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;

        Edge *e = nodes[u].edges;
        while (e) {
            if (!visited[e->to] && dist[u] + e->weight < dist[e->to]) {
                dist[e->to] = dist[u] + e->weight;
            }
            e = e->next;
        }
    }

    /* Sort node indices alphabetically */
    int *order = malloc(node_count * sizeof(int));
    for (int i = 0; i < node_count; i++) order[i] = i;
    for (int i = 0; i < node_count - 1; i++) {
        for (int j = 0; j < node_count - 1 - i; j++) {
            if (strcmp(nodes[order[j]].name, nodes[order[j + 1]].name) > 0) {
                int tmp = order[j];
                order[j] = order[j + 1];
                order[j + 1] = tmp;
            }
        }
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n");
    printf("\n");
    for (int i = 0; i < node_count; i++) {
        int idx = order[i];
        if (dist[idx] >= INF / 2) {
            printf("A -> %s: unreachable\n", nodes[idx].name);
        } else if (dist[idx] == (double)(long long)dist[idx]) {
            printf("A -> %s: %lld\n", nodes[idx].name, (long long)dist[idx]);
        } else {
            printf("A -> %s: %g\n", nodes[idx].name, dist[idx]);
        }
    }

    /* Cleanup */
    for (int i = 0; i < node_count; i++) {
        Edge *e = nodes[i].edges;
        while (e) {
            Edge *tmp = e;
            e = e->next;
            free(tmp);
        }
    }
    free(nodes);
    free(dist);
    free(visited);
    free(order);
    free(json);

    return 0;
