static int file_cap = 0;

static char *concat_paths(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    char *r = malloc(la + 1 + lb + 1);
    if (!r) exit(1);
    memcpy(r, a, la);
    r[la] = '/';
    memcpy(r + la + 1, b, lb + 1);
    return r;
}

static void add_file(const char *relpath, long lines, long chars) {
    if (file_count == file_cap) {
        file_cap = file_cap ? file_cap * 2 : 128;
        files = realloc(files, file_cap * sizeof(FileInfo));
        if (!files) exit(1);
    }
    files[file_count].relpath = strdup(relpath);
    if (!files[file_count].relpath) exit(1);
    files[file_count].lines = lines;
    files[file_count].chars = chars;
    const char *base = strrchr(relpath, '/');
    base = base ? base + 1 : relpath;
    const char *dot = strrchr(base, '.');
    if (dot && dot != base) {
        files[file_count].ext = strdup(dot);
    } else {
        files[file_count].ext = strdup("");
    }
    if (!files[file_count].ext) exit(1);
    file_count++;
}

static void count_file(const char *path, long *lines, long *chars) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        *lines = 0;
        *chars = 0;
        return;
    }
    *lines = 0;
    *chars = 0;
    int prev = -1;
    size_t bufsize = 65536;
    unsigned char *buf = malloc(bufsize);
    if (!buf) {
        fclose(f);
        *lines = 0;
        *chars = 0;
        return;
