    size_t n;
    while ((n = fread(buf, 1, bufsize, f)) > 0) {
        for (size_t i = 0; i < n; i++) {
            (*chars)++;
            if (buf[i] == '\n') (*lines)++;
            prev = (int)buf[i];
        }
    }
    if (*chars > 0 && prev != '\n') (*lines)++;
    free(buf);
    fclose(f);
}

static void walk(const char *dir, const char *reldir) {
    DIR *d = opendir(dir);
    if (!d) return;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char *fullpath = concat_paths(dir, entry->d_name);
        char *relpath;
