#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(pairs) = self {
            for (k, v) in pairs {
                if k == key {
                    return Some(v);
                }
            }
        }
        None
    }

    fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self {
            Some(s)
        } else {
            None
        }
    }

    fn as_f64(&self) -> Option<f64> {
        if let Json::Number(n) = self {
            Some(*n)
        } else {
            None
        }
    }
}

struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { data: s.as_bytes(), pos: 0 }
    }

    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<u8> {
        let c = self.data.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Json::Str(self.parse_string()),
            Some(b't') => {
                self.expect_literal(b"true");
                Json::Bool(true)
            }
            Some(b'f') => {
                self.expect_literal(b"false");
                Json::Bool(false)
            }
            Some(b'n') => {
                self.expect_literal(b"null");
                Json::Null
            }
            _ => Json::Number(self.parse_number()),
        }
    }

    fn expect_literal(&mut self, s: &[u8]) {
        for &c in s {
            let got = self.next().unwrap();
            assert_eq!(got, c, "JSON parse error");
        }
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut code = 0u32;
        for _ in 0..4 {
            let h = self.next().unwrap();
            let d = match h {
                b'0'..=b'9' => (h - b'0') as u32,
                b'a'..=b'f' => (h - b'a' + 10) as u32,
                b'A'..=b'F' => (h - b'A' + 10) as u32,
                _ => 0,
            };
            code = code * 16 + d;
        }
        code
    }

    fn parse_string(&mut self) -> String {
        self.next(); // consume opening "
        let mut result: Vec<u8> = Vec::new();
        loop {
            let c = self.next().unwrap();
            if c == b'"' {
                break;
            } else if c == b'\\' {
                let esc = self.next().unwrap();
                match esc {
                    b'"' => result.push(b'"'),
                    b'\\' => result.push(b'\\'),
                    b'/' => result.push(b'/'),
                    b'n' => result.push(b'\n'),
                    b't' => result.push(b'\t'),
                    b'r' => result.push(b'\r'),
                    b'b' => result.push(0x08),
                    b'f' => result.push(0x0C),
                    b'u' => {
                        let code = self.parse_hex4();
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.peek() == Some(b'\\') {
                                self.next();
                                if self.peek() == Some(b'u') {
                                    self.next();
                                    let low = self.parse_hex4();
                                    if (0xDC00..=0xDFFF).contains(&low) {
                                        let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                        if let Some(ch) = char::from_u32(cp) {
                                            let mut buf = [0u8; 4];
                                            result.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                                        }
                                    }
                                }
                            }
                        } else {
                            if let Some(ch) = char::from_u32(code) {
                                let mut buf = [0u8; 4];
                                result.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            }
                        }
                    }
                    _ => result.push(esc),
                }
            } else {
                result.push(c);
            }
        }
        String::from_utf8(result).unwrap_or_default()
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;
        if self.peek() == Some(b'-') {
            self.next();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == b'.' || c == b'e' || c == b'E' || c == b'+' || c == b'-' {
                self.next();
            } else {
                break;
            }
        }
        let s = std::str::from_utf8(&self.data[start..self.pos]).unwrap_or("0");
        s.parse::<f64>().unwrap_or(0.0)
    }

    fn parse_array(&mut self) -> Json {
        self.next(); // consume [
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b']') {
            self.next();
            return Json::Arr(arr);
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(b',') => continue,
                Some(b']') => break,
                _ => break,
            }
        }
        Json::Arr(arr)
    }

    fn parse_object(&mut self) -> Json {
        self.next(); // consume {
        let mut obj = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.next();
            return Json::Obj(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next(); // consume :
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(b',') => continue,
                Some(b'}') => break,
                _ => break,
            }
        }
        Json::Obj(obj)
    }
}

fn decode_chunked(data: &str) -> String {
    let mut result = String::new();
    let bytes = data.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        let line_end = match data[pos..].find('\n') {
            Some(i) => pos + i,
            None => break,
        };
        let size_str = data[pos..line_end].trim_end_matches('\r').trim();
        let size = match usize::from_str_radix(size_str, 16) {
            Ok(s) => s,
            Err(_) => break,
        };
        if size == 0 {
            break;
        }
        pos = line_end + 1;
        if pos + size > bytes.len() {
            break;
        }
        result.push_str(&data[pos..pos + size]);
        pos += size;
        if pos + 1 < bytes.len() && bytes[pos] == b'\r' && bytes[pos + 1] == b'\n' {
            pos += 2;
        } else if pos < bytes.len() && bytes[pos] == b'\n' {
            pos += 1;
        }
    }
    result
}

fn http_get(host: &str, port: u16, path: &str) -> String {
    let mut stream = TcpStream::connect((host, port)).expect("Failed to connect");
    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
        path, host
    );
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    let mut buf = Vec::new();
    let mut tmp = [0u8; 4096];
    loop {
        match stream.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => buf.extend_from_slice(&tmp[..n]),
            Err(_) => break,
        }
    }

    let response = String::from_utf8_lossy(&buf).to_string();

    let header_end = response
        .find("\r\n\r\n")
        .map(|i| i + 4)
        .or_else(|| response.find("\n\n").map(|i| i + 2))
        .unwrap_or(0);

    let headers = response[..header_end].to_lowercase();
    let body = &response[header_end..];

    if headers.contains("transfer-encoding: chunked") {
        decode_chunked(body)
    } else {
        body.to_string()
    }
}

fn main() {
    let body = http_get("127.0.0.1", 18924, "/api/products");
    let mut parser = Parser::new(&body);
    let json = parser.parse_value();

    let products: Vec<Json> = match &json {
        Json::Arr(arr) => arr.clone(),
        _ => vec![],
    };

    let mut filtered: Vec<(String, f64)> = Vec::new();
    for product in &products {
        let price = product.get("price").and_then(|v| v.as_f64()).unwrap_or(0.0);
        if price > 50.00 {
            let name = product
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            filtered.push((name, price));
        }
    }

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    let mut total = 0.0;
    for (_, price) in &filtered {
        total += price;
    }

    print!("=== Filtered Products (price > $50.00) ===\n");
    print!("\n");
    for (name, price) in &filtered {
        print!("{}: ${:.2}\n", name, price);
    }
    print!("\n");
    print!("Count: {}\n", filtered.len());
    print!("Total: ${:.2}\n", total);
}

