        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') (*pos)++;
        else break;
    }
}

static char *parse_string_content(const char *s, int *pos, int len) {
    (*pos)++;
    int cap = 64;
    char *buf = (char *)malloc((size_t)cap);
    int blen = 0;

    while (*pos < len && s[*pos] != '"') {
        char c = s[*pos];
        if (c == '\\') {
            (*pos)++;
            if (*pos >= len) break;
            char esc = s[*pos];
            if (esc == 'u') {
                (*pos)++;
                unsigned int code = 0;
                for (int i = 0; i < 4; i++) {
                    if (*pos >= len) break;
                    char h = s[*pos];
                    (*pos)++;
                    code <<= 4;
                    if (h >= '0' && h <= '9') code |= (unsigned)(h - '0');
                    else if (h >= 'a' && h <= 'f') code |= (unsigned)(h - 'a' + 10);
                    else if (h >= 'A' && h <= 'F') code |= (unsigned)(h - 'A' + 10);
                }
                if (code < 0x80) {
                    if (blen + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, (size_t)cap); }
                    buf[blen++] = (char)code;
                } else if (code < 0x800) {
                    if (blen + 2 >= cap) { cap *= 2; buf = (char *)realloc(buf, (size_t)cap); }
                    buf[blen++] = (char)(0xC0 | (code >> 6));
                    buf[blen++] = (char)(0x80 | (code & 0x3F));
                } else {
                    if (blen + 3 >= cap) { cap *= 2; buf = (char *)realloc(buf, (size_t)cap); }
                    buf[blen++] = (char)(0xE0 | (code >> 12));
                    buf[blen++] = (char)(0x80 | ((code >> 6) & 0x3F));
                    buf[blen++] = (char)(0x80 | (code & 0x3F));
                }
            } else {
                (*pos)++;
                char out = esc;
                switch (esc) {
                    case '"': out = '"'; break;
                    case '\\': out = '\\'; break;
                    case '/': out = '/'; break;
                    case 'b': out = '\b'; break;
                    case 'f': out = '\f'; break;
                    case 'n': out = '\n'; break;
                    case 'r': out = '\r'; break;
                    case 't': out = '\t'; break;
                    default: out = esc; break;
                }
                if (blen + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, (size_t)cap); }
                buf[blen++] = out;
            }
        } else {
            if (blen + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, (size_t)cap); }
            buf[blen++] = c;
            (*pos)++;
        }
    }

    if (*pos < len && s[*pos] == '"') (*pos)++;

    if (blen + 1 > cap) { cap = blen + 1; buf = (char *)realloc(buf, (size_t)cap); }
    buf[blen] = '\0';
    return buf;
}

static json_value *parse_value(const char *s, int *pos, int len) {
    skip_ws(s, pos, len);
    if (*pos >= len) return new_json(JSON_NULL);

    char c = s[*pos];

    if (c == '{') {
        json_value *obj = new_json(JSON_OBJECT);
        (*pos)++;
        skip_ws(s, pos, len);
        if (*pos < len && s[*pos] == '}') {
            (*pos)++;
            return obj;
        }
        while (1) {
            skip_ws(s, pos, len);
            if (*pos >= len) break;
            if (s[*pos] != '"') break;
            char *key = parse_string_content(s, pos, len);
            skip_ws(s, pos, len);
            if (*pos >= len || s[*pos] != ':') { free(key); break; }
            (*pos)++;
            json_value *val = parse_value(s, pos, len);
            add_object_pair(obj, key, val);
            skip_ws(s, pos, len);
            if (*pos < len && s[*pos] == ',') {
                (*pos)++;
                continue;
            } else if (*pos < len && s[*pos] == '}') {
                (*pos)++;
                break;
            } else {
                break;
            }
        }
        return obj;
    }

    if (c == '[') {
        json_value *arr = new_json(JSON_ARRAY);
        (*pos)++;
        skip_ws(s, pos, len);
        if (*pos < len && s[*pos] == ']') {
            (*pos)++;
            return arr;
        }
        while (1) {
            json_value *item = parse_value(s, pos, len);
            add_array_item(arr, item);
            skip_ws(s, pos, len);
            if (*pos < len && s[*pos] == ',') {
                (*pos)++;
                continue;
            } else if (*pos < len && s[*pos] == ']') {
                (*pos)++;
                break;
            } else {
                break;
            }
        }
        return arr;
    }

    if (c == '"') {
        json_value *str = new_json(JSON_STRING);
        str->string = parse_string_content(s, pos, len);
        return str;
    }

    if (c == 't') {
        if (len - *pos >= 4 && strncmp(s + *pos, "true", 4) == 0) {
            *pos += 4;
            json_value *v = new_json(JSON_BOOL);
            v->boolean = 1;
            return v;
        }
    }

    if (c == 'f') {
        if (len - *pos >= 5 && strncmp(s + *pos, "false", 5) == 0) {
            *pos += 5;
            json_value *v = new_json(JSON_BOOL);
            v->boolean = 0;
            return v;
        }
    }

    if (c == 'n') {
        if (len - *pos >= 4 && strncmp(s + *pos, "null", 4) == 0) {
            *pos += 4;
            return new_json(JSON_NULL);
        }
    }

    if (c == '-' || (c >= '0' && c <= '9')) {
        char *end;
        double val = strtod(s + *pos, &end);
        *pos += (int)(end - (s + *pos));
        json_value *v = new_json(JSON_NUMBER);
        v->number = val;
        return v;
    }

    return new_json(JSON_NULL);
}

static int json_equal(json_value *a, json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING:
            return a->string && b->string && strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++) {
                if (!json_equal(a->items[i], b->items[i])) return 0;
            }
            return 1;
        case JSON_OBJECT:
            if (a->pair_count != b->pair_count) return 0;
            for (int i = 0; i < a->pair_count; i++) {
                int found = 0;
                for (int j = 0; j < b->pair_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equal(a->values[i], b->values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

static json_value *deep_merge(json_value *a, json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = new_json(JSON_OBJECT);
        for (int i = 0; i < a->pair_count; i++) {
            int found_in_b = -1;
            for (int j = 0; j < b->pair_count; j++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    found_in_b = j;
                    break;
                }
            }
            if (found_in_b >= 0) {
                json_value *merged = deep_merge(a->values[i], b->values[found_in_b]);
                add_object_pair(result, strdup(a->keys[i]), merged);
            } else {
                add_object_pair(result, strdup(a->keys[i]), a->values[i]);
            }
        }
        for (int j = 0; j < b->pair_count; j++) {
            int found_in_a = -1;
            for (int i = 0; i < a->pair_count; i++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    found_in_a = i;
                    break;
                }
            }
            if (found_in_a < 0) {
                add_object_pair(result, strdup(b->keys[j]), b->values[j]);
            }
        }
        return result;
    }

    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = new_json(JSON_ARRAY);
        for (int i = 0; i < a->item_count; i++) {
            add_array_item(result, a->items[i]);
        }
        for (int j = 0; j < b->item_count; j++) {
            int dup = 0;
            for (int i = 0; i < result->item_count; i++) {
                if (json_equal(result->items[i], b->items[j])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                add_array_item(result, b->items[j]);
            }
        }
        return result;
    }

    return b;
}

static void sort_object_keys(json_value *obj) {
    int n = obj->pair_count;
    if (n <= 1) return;
    for (int i = 1; i < n; i++) {
        char *key = obj->keys[i];
        json_value *val = obj->values[i];
        int j = i - 1;
        while (j >= 0 && strcmp(obj->keys[j], key) > 0) {
            obj->keys[j + 1] = obj->keys[j];
            obj->values[j + 1] = obj->values[j];
            j--;
        }
        obj->keys[j + 1] = key;
        obj->values[j + 1] = val;
    }
}

static void print_escaped_string(const char *s) {
    printf("\"");
    for (int i = 0; s[i]; i++) {
        unsigned char c = (unsigned char)s[i];
        switch (c) {
            case '"': printf("\\\""); break;
            case '\\': printf("\\\\"); break;
            case '\b': printf("\\b"); break;
            case '\f': printf("\\f"); break;
            case '\n': printf("\\n"); break;
            case '\r': printf("\\r"); break;
            case '\t': printf("\\t"); break;
            default:
                if (c < 0x20) {
                    printf("\\u%04x", c);
                } else {
                    printf("%c", c);
                }
                break;
        }
    }
    printf("\"");
}

static void print_number(double n) {
    if (n == floor(n) && fabs(n) < 1e15) {
        printf("%lld", (long long)n);
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.10g", n);
        printf("%s", buf);
    }
}

static void print_value(json_value *v, int indent) {
    switch (v->type) {
        case JSON_NULL:
            printf("null");
            break;
        case JSON_BOOL:
            printf(v->boolean ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(v->number);
            break;
        case JSON_STRING:
            print_escaped_string(v->string);
            break;
        case JSON_ARRAY:
            if (v->item_count == 0) {
                printf("[]");
                break;
            }
            printf("[\n");
            for (int i = 0; i < v->item_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) printf(" ");
                print_value(v->items[i], indent + 1);
                if (i < v->item_count - 1) printf(",");
                printf("\n");
            }
            for (int s = 0; s < indent * 2; s++) printf(" ");
            printf("]");
            break;
        case JSON_OBJECT:
            if (v->pair_count == 0) {
                printf("{}");
                break;
            }
            sort_object_keys(v);
            printf("{\n");
            for (int i = 0; i < v->pair_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) printf(" ");
                print_escaped_string(v->keys[i]);
                printf(": ");
                print_value(v->values[i], indent + 1);
                if (i < v->pair_count - 1) printf(",");
                printf("\n");
            }
            for (int s = 0; s < indent * 2; s++) printf(" ");
            printf("}");
            break;
    }
}

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (size < 0) { fclose(f); return NULL; }
    char *buf = (char *)malloc((size_t)size + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)size, f);
    fclose(f);
    buf[rd] = '\0';
    *out_len = (int)rd;
    return buf;
}

